import{_ as i,l,o as e,c as n,v as t,p as s,x as r,d,i as E,S as h}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"难负例挖掘","description":"","frontmatter":{"title":"难负例挖掘","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/hard-negatives.md","filePath":"llm/hard-negatives.md","lastUpdated":1789023840000}'),p={name:"llm/hard-negatives.md"};function c(_,a,A,m,B,u){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="难负例挖掘" tabindex="-1">难负例挖掘 <a class="header-anchor" href="#难负例挖掘" aria-label="Permalink to &quot;难负例挖掘&quot;">​</a></h1><div class="epigraph"><p>批内随机负例太容易，模型学会的是主题分类。要把「看起来像、其实不答」的文档挖出来，度量才进入细粒度。</p><footer>—— Karpukhin 等 DPR 的 BM25 负例；Xiong 等 ANCE 的用当前模型挖负例</footer></div><p><a href="/llm/contrastive-infonce">上一课</a>的 InfoNCE 梯度由高分负例主导。随机批内负例分数往往很低，梯度接近零。本课写难负例。缺口是训练分布：负例从哪来、何时会变成假负。后课 Matryoshka 默认空间已经靠难负例撑开，而不是靠加维。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Karpukhin 的 DPR 用 BM25 检索到的高分但标注不相关的段落当负例，比随机负例强。静态挖一次会过时：模型更新后，难例集合不再难。Xiong 等 ANCE 用当前检查点异步建索引、检索难负例，空间跟着模型走。RocketQA 等再引入交叉编码器去假负：双塔认为难、交叉编码器认为相关的，不当负例。</p><p>假负例会伤害召回：同义改写被推远。只追「最难」还会不稳定，损失被少数噪声对主导。需要混合：随机、BM25、模型挖到的、以及少量金标难负。</p><p><span class="marginnote">难负例不是越多越难越好。验证应看细粒度对（易混淆实体、相反极性），不是只看主题级召回。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流水线：用现索引对训练查询取 Top-\\(n\\) 非正例 → 可选交叉编码器过滤 → 与批内随机负例混合进 InfoNCE。更新频率：过勤则索引抖动、过慢则负例变易。文档侧挖掘（对每个文档找易混查询）对称可用。标注预算应花在「双塔高分、标注员说不相关」的切片上。</p>',9)),(e(),s(h,null,{default:r(()=>[E(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%AE%AD%E7%BB%83%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20RET%5B%22%E5%BD%93%E5%89%8D%E6%A3%80%E7%B4%A2%E5%99%A8%20Top-n%22%5D%0A%20%20RET%20--%3E%20FIL%5B%22%E4%BA%A4%E5%8F%89%E7%BC%96%E7%A0%81%E5%99%A8%E5%8E%BB%E5%81%87%E8%B4%9F%22%5D%0A%20%20FIL%20--%3E%20MIX%5B%22%E4%B8%8E%E9%9A%8F%E6%9C%BA%E8%B4%9F%E4%BE%8B%E6%B7%B7%E5%90%88%22%5D%0A%20%20MIX%20--%3E%20L%5B%22InfoNCE%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>随机负例只要求 \\(z_q\\) 离开无关主题的云团。难负例要求在同一主题云团内部把正确段落与近邻段落分开，于是表示必须编码约束、实体与极性。ANCE 的异步更新是在对正在移动的流形做近似硬负采样；延迟过大，挖到的是旧流形上的难例，对新模型又变易。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>没有标注时，交叉编码器本身会错，去假负会去掉真难例。应抽检。下一课 Matryoshka：同一套对比目标下，如何让截断后的短向量仍然可用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>难负例把对比学习从主题分类推进到细粒度匹配。</li><li>静态 BM25 负例会过时；用当前模型挖并去假负。</li><li>与随机负例混合，避免被噪声对主导。</li><li>出处：Karpukhin 等 DPR；Xiong 等 ANCE；RocketQA 去假负。</li></ul>',6))])}const k=i(p,[["render",c]]);export{T as __pageData,k as default};
